// SPDX-License-Identifier: GPL-2.0-or-later
// EXPERIMENT ONLY: ordered PFFFT adapter, never installed in a plug-in.
#include "fft.hpp"
#include "third_party/ooura/fftsg.hpp"
#include <array>
#include <pffft/pffft.h>
#include <algorithm>
#include <bit>
#include <memory>
#include <stdexcept>

namespace convolver {
const char* fft_backend_name() noexcept { return "PFFFT-experimental"; }
const char* fft_backend_version() noexcept { return "237ffa283b17 ordered NEON"; }
bool fft_supports_wisdom() noexcept { return false; }
void import_fft_wisdom(std::string_view) { throw std::invalid_argument("wisdom requires FFTW"); }
std::string export_fft_wisdom() { throw std::invalid_argument("wisdom requires FFTW"); }
namespace detail {
void check_fft_options(const FftOptions& o) {
    if (o.planning != FftPlanning::estimate || o.wisdom_only || o.time_limit_seconds != 0)
        throw std::invalid_argument("measured planning and wisdom require FFTW");
}
std::size_t fft_size(std::size_t b) noexcept { return std::max(std::size_t(4), std::bit_ceil(2*b)); }
std::size_t fft_storage(std::size_t n) noexcept {
    // Four owned buffers plus N twiddles and an upper allowance for setup/alignment.
    return 5*n + 256;
}
struct Free { void operator()(float* p) const noexcept { pffft_aligned_free(p); } };
using Buffer = std::unique_ptr<float, Free>;
Buffer buffer(std::size_t n) {
    auto p = Buffer(static_cast<float*>(pffft_aligned_malloc(n*sizeof(float))));
    if (!p) throw std::bad_alloc();
    std::fill_n(p.get(), n, 0.f);
    return p;
}
struct Destroy { void operator()(PFFFT_Setup* p) const noexcept { pffft_destroy_setup(p); } };
struct RealFft::Impl {
    std::size_t n;
    Buffer time, frequency, sum, work;
    std::unique_ptr<PFFFT_Setup, Destroy> setup;
    std::array<float,16> twiddles{};
    std::array<int,8> bits{};
    explicit Impl(std::size_t size, FftOptions options)
        : n(size), time(buffer(n)), frequency(buffer(n+2)), sum(buffer(n+2)), work(buffer(n)) {
        check_fft_options(options);
        if (n < 32) {
            ooura::rdft(static_cast<int>(n),1,work.get(),bits.data(),twiddles.data());
            return;
        }
        setup.reset(pffft_new_setup(static_cast<int>(n), PFFFT_REAL));
        if (!setup) throw std::runtime_error("PFFFT setup failed for N=" + std::to_string(n));
    }
};
RealFft::RealFft(std::size_t n, FftOptions o) : impl_(std::make_unique<Impl>(n,o)) {}
RealFft::~RealFft() = default;
float* RealFft::time() noexcept { return impl_->time.get(); }
float* RealFft::frequency() noexcept { return impl_->frequency.get(); }
float* RealFft::sum() noexcept { return impl_->sum.get(); }
void RealFft::forward() noexcept {
    auto& s = *impl_;
    if (s.n < 32) {
        std::copy_n(s.time.get(),s.n,s.work.get());
        ooura::rdft(static_cast<int>(s.n),1,s.work.get(),s.bits.data(),s.twiddles.data());
        std::copy_n(s.work.get(),s.n,s.frequency.get());
        for (std::size_t k=1;k<s.n/2;++k) s.frequency.get()[2*k+1] *= -1;
    } else pffft_transform_ordered(s.setup.get(), s.time.get(), s.frequency.get(), s.work.get(), PFFFT_FORWARD);
    s.frequency.get()[s.n] = s.frequency.get()[1];
    s.frequency.get()[1] = s.frequency.get()[s.n+1] = 0;
}
void RealFft::inverse() noexcept {
    auto& s = *impl_;
    if (s.n < 32) {
        s.time.get()[0] = 2*s.sum.get()[0];
        s.time.get()[1] = 2*s.sum.get()[s.n];
        for (std::size_t k=1;k<s.n/2;++k) {
            s.time.get()[2*k]=2*s.sum.get()[2*k];
            s.time.get()[2*k+1]=-2*s.sum.get()[2*k+1];
        }
        ooura::rdft(static_cast<int>(s.n),-1,s.time.get(),s.bits.data(),s.twiddles.data());
        return;
    }
    s.sum.get()[1] = s.sum.get()[s.n];
    pffft_transform_ordered(s.setup.get(), s.sum.get(), s.time.get(), s.work.get(), PFFFT_BACKWARD);
    s.sum.get()[1] = 0;
}
} // namespace detail
} // namespace convolver
